import random, subprocess, itertools

def max_pairs(arr):
    n=len(arr)
    # dp over masks: maximum pairs among used vertices (leave/unpair)
    from functools import lru_cache
    @lru_cache(None)
    def f(mask):
        # find first unused
        try:
            i=next(i for i in range(n) if not (mask>>i)&1)
        except StopIteration:
            return 0
        best=f(mask|(1<<i))  # leave i unused
        for j in range(i+1,n):
            if not (mask>>j)&1 and 2*arr[i]<=arr[j]:
                v=1+f(mask|(1<<i)|(1<<j))
                if v>best: best=v
        return best
    return f(0)

