import itertools, subprocess
from collections import deque

def brute(N,P):
    pairs=list(itertools.combinations(range(N),2))
    E=len(pairs)
    maxm=N*(N-1)//2
    cnt=[0]*(maxm+1)
    for mask in range(1<<E):
        adj=[[] for _ in range(N)]
        m=bin(mask).count('1')
        for k,(u,v) in enumerate(pairs):
            if mask>>k&1:
                adj[u].append(v); adj[v].append(u)
        seen=[False]*N; seen[0]=True; dq=deque([0]); c=1
        while dq:
            u=dq.popleft()
            for v in adj[u]:
                if not seen[v]: seen[v]=True;c+=1;dq.append(v)
        if c!=N: continue
        dist=[-1]*N; dist[0]=0; dq=deque([0])
        while dq:
            u=dq.popleft()
            for v in adj[u]:
                if dist[v]<0: dist[v]=dist[u]+1; dq.append(v)
        ev=sum(1 for x in dist if x%2==0)
        od=N-ev
        if ev==od: cnt[m]+=1
    return [cnt[m]%P for m in range(N-1,maxm+1)]

for N,P in [(2,100000007),(4,100000007),(6,100000007),(6,998244353)]:
