    r=subprocess.run(['python3','solutions/abc389_g.py'],input=inp,text=True,capture_output=True)
    got=list(map(int,r.stdout.split()))
    exp=brute(N,P)
    print(N,P,'OK' if got==exp else 'FAIL',got,exp)
